window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c8c0ca0308cdb65b"]={"versions": [{"id": "FIG-c8c0ca0308cdb65b", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architekturdiagramm eines Gateway-Steuergeräts (Gateway ECU) im Kontext des AUTOSAR System Templates. Das Diagramm illustriert das architektonische Muster für die Signal-Service-Übersetzung (Signal Service Translation) oberhalb der AUTOSAR-Laufzeitumgebung (RTE) mittels einer anwendungsspezifischen Software-Komponente (Translation Application SWC). Es veranschaulicht den Datenfluss und die Transformationskette zwischen klassischer signalbasierter Kommunikation (Com Pdu) und serviceorientierter Kommunikation (SOME/IP Serialized Bytes mit SOME/IP Header).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Gateway ECU</strong>: Umfassender Steuergeräte-Knoten als Ausführungskontext.\n</li><li><strong>Translation Application SWC</strong>: Anwendungskomponente oberhalb der RTE, beinhaltet die Entität <code>Signal Service Mapping</code> zur Zuordnung von Signalen zu Services. Sie verfügt über zwei Ports (P-Port/R-Port) zur RTE.\n</li><li><strong>RTE (Runtime Infrastructure / VFB)</strong>: Zentraler Vermittler zwischen Anwendungs-SWC und Basissoftware/Transformern.\n</li><li><strong>Transformationsketten</strong>:\n<ul class=\"fig-list\"><li><em>Signal-Empfangsseite (rechts)</em>: Kaskadierung aus <code>COM Based Transformer</code> und <code>E2E Transformer</code> zur Deserialisierung/Dekodierung und E2E-Validierung eingehender Signale.\n</li><li><em>Service-Sendeseite (links)</em>: Kaskadierung aus <code>Serializer</code> und <code>E2E Transformer</code> zur Serialisierung in SOME/IP-Payloads und Anfügen von E2E-Schutzmechanismen.\n</li></ul>\n</li><li><strong>COM-Stack</strong>: Kommunikationsstapel mit Repräsentation der PDU-Strukturen:\n<ul class=\"fig-list\"><li><code>Com Pdu</code>: Signalbasierte PDU mit den Elementen <code>a</code>, <code>d</code>, <code>c</code>, <code>b</code>.\n</li><li><code>SOME/IP Serialized Bytes</code>: Serviceorientierte Payload mit den serialisierten Elementen <code>a</code>, <code>b</code>, <code>c</code>, <code>d</code>, vorangestellt ist der <code>SOME/IP Header</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Signalempfang</strong>: Eine eingehende <code>Com Pdu</code> (Signale a, d, c, b) wird vom <code>COM-Stack</code> über die RTE an die Empfangs-Transformationskette (<code>COM Based Transformer</code> und <code>E2E Transformer</code>) übergeben.\n</li><li><strong>Signaltransformation &amp; Bereitstellung</strong>: Nach Prüfung und Dekodierung leitet die RTE die extrahierten Signale über einen Port an die <code>Translation Application SWC</code> weiter.\n</li><li><strong>Signal-Service-Mapping</strong>: Innerhalb der SWC erfolgt die fachliche Umsetzung (<code>Signal Service Mapping</code>) zwischen den Signalelementen und den entsprechenden Feldern/Attributen des Ziel-Service.\n</li><li><strong>Service-Ausgabe &amp; Serialisierung</strong>: Die SWC übergibt die Daten über den Sendeport an die RTE. Die RTE führt die Daten durch den <code>Serializer</code> (Serialisierung der Felder a, b, c, d) und den <code>E2E Transformer</code>.\n</li><li><strong>PDU-Generierung</strong>: Die resultierenden <code>SOME/IP Serialized Bytes</code> werden mitsamt <code>SOME/IP Header</code> an den <code>COM-Stack</code> zur Weitersendung als Ethernet-/IP-Paket übergeben.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Muster gilt normativ für Events und Field-Notifier in Gateway-Szenarien, bei denen Signale auf Service-Events übersetzt werden. Methodenaufrufe (Client/Server) werden separat behandelt (siehe Abschnitt 6.15.1.1). Entwickler müssen sicherstellen, dass die Transformationsketten in der RTE für beide Kommunikationspfade (COM-basiert vs. SOME/IP-Serialisierung) sowie die jeweiligen E2E-Transformationsprofile konsistent mit den PDU-Definitionen im System Description File konfiguriert sind.</p>"}, {"id": "FIG-9d7dae1d2c920380", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architekturdiagramm eines Gateway-Steuergeräts (Gateway ECU) im Kontext des AUTOSAR System Templates. Das Diagramm illustriert das architektonische Muster für die Signal-Service-Übersetzung (Signal Service Translation) oberhalb der AUTOSAR-Laufzeitumgebung (RTE) mittels einer anwendungsspezifischen Software-Komponente (Translation Application SWC). Es veranschaulicht den Datenfluss und die Transformationskette zwischen klassischer signalbasierter Kommunikation (Com Pdu) und serviceorientierter Kommunikation (SOME/IP Serialized Bytes mit SOME/IP Header).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Gateway ECU</strong>: Umfassender Steuergeräte-Knoten als Ausführungskontext.\n</li><li><strong>Translation Application SWC</strong>: Anwendungskomponente oberhalb der RTE, beinhaltet die Entität <code>Signal Service Mapping</code> zur Zuordnung von Signalen zu Services. Sie verfügt über zwei Ports (P-Port/R-Port) zur RTE.\n</li><li><strong>RTE (Runtime Infrastructure / VFB)</strong>: Zentraler Vermittler zwischen Anwendungs-SWC und Basissoftware/Transformern.\n</li><li><strong>Transformationsketten</strong>:\n<ul class=\"fig-list\"><li><em>Signal-Empfangsseite (rechts)</em>: Kaskadierung aus <code>COM Based Transformer</code> und <code>E2E Transformer</code> zur Deserialisierung/Dekodierung und E2E-Validierung eingehender Signale.\n</li><li><em>Service-Sendeseite (links)</em>: Kaskadierung aus <code>Serializer</code> und <code>E2E Transformer</code> zur Serialisierung in SOME/IP-Payloads und Anfügen von E2E-Schutzmechanismen.\n</li></ul>\n</li><li><strong>COM-Stack</strong>: Kommunikationsstapel mit Repräsentation der PDU-Strukturen:\n<ul class=\"fig-list\"><li><code>Com Pdu</code>: Signalbasierte PDU mit den Elementen <code>a</code>, <code>d</code>, <code>c</code>, <code>b</code>.\n</li><li><code>SOME/IP Serialized Bytes</code>: Serviceorientierte Payload mit den serialisierten Elementen <code>a</code>, <code>b</code>, <code>c</code>, <code>d</code>, vorangestellt ist der <code>SOME/IP Header</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Signalempfang</strong>: Eine eingehende <code>Com Pdu</code> (Signale a, d, c, b) wird vom <code>COM-Stack</code> über die RTE an die Empfangs-Transformationskette (<code>COM Based Transformer</code> und <code>E2E Transformer</code>) übergeben.\n</li><li><strong>Signaltransformation &amp; Bereitstellung</strong>: Nach Prüfung und Dekodierung leitet die RTE die extrahierten Signale über einen Port an die <code>Translation Application SWC</code> weiter.\n</li><li><strong>Signal-Service-Mapping</strong>: Innerhalb der SWC erfolgt die fachliche Umsetzung (<code>Signal Service Mapping</code>) zwischen den Signalelementen und den entsprechenden Feldern/Attributen des Ziel-Service.\n</li><li><strong>Service-Ausgabe &amp; Serialisierung</strong>: Die SWC übergibt die Daten über den Sendeport an die RTE. Die RTE führt die Daten durch den <code>Serializer</code> (Serialisierung der Felder a, b, c, d) und den <code>E2E Transformer</code>.\n</li><li><strong>PDU-Generierung</strong>: Die resultierenden <code>SOME/IP Serialized Bytes</code> werden mitsamt <code>SOME/IP Header</code> an den <code>COM-Stack</code> zur Weitersendung als Ethernet-/IP-Paket übergeben.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Muster gilt normativ für Events und Field-Notifier in Gateway-Szenarien, bei denen Signale auf Service-Events übersetzt werden. Methodenaufrufe (Client/Server) werden separat behandelt (siehe Abschnitt 6.16.1.1). Entwickler müssen sicherstellen, dass die Transformationsketten in der RTE für beide Kommunikationspfade (COM-basiert vs. SOME/IP-Serialisierung) sowie die jeweiligen E2E-Transformationsprofile konsistent mit den PDU-Definitionen im System Description File konfiguriert sind.</p>"}], "trans": [{"from": "FIG-c8c0ca0308cdb65b", "to": "FIG-9d7dae1d2c920380", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Text oberhalb der Gateway-ECU: Der Abschnittsverweis für die separate Behandlung von Methoden wurde redaktionell von „6.15.1.1“ auf „6.16.1.1“ aktualisiert.\n</li></ul>"}]};
